                $range[$i][$j] = $cellReferenceHelper->updateCellReference($range[$i][$j], $includeAbsoluteReferences, $onlyAbsoluteReferences);
            }
        }
    }

    // Recreate range string
    return Coordinate::buildRange($range);
}

